ee:message.ee:set-payload:
%dw 2.0
output application/json
---
payload match {
    case is Array -> payload  // Already parsed
    case is String -> 
        payload readCsv using {
            header: true,
            separator: ",",
            quote: "\"",
            escape: "\\"
        } map ((row) -> {
            // Dynamically map all fields from CSV headers
            // Type inference: attempt numeric conversion where applicable
            ($) mapObject ((value, key, index) -> {
                (key): value match {
                    // Attempt to detect numeric fields
                    case s: String if (s matches /^-?\d+(\.\d+)?$/) -> s as Number
                    else -> s
                }
            })
        })
    else -> []
}

%dw 2.0
output application/json
---
// Dynamically extract field names from the first record
var fieldNames = if (isEmpty(payload)) [] else (payload[0] pluck $$)
---
{
    // Detect mandatory fields heuristically
    allFields: fieldNames,
    valid: payload filter ((record) ->
        !isEmpty(record.Amount) and
        !isEmpty(record.CreditAccountNumber) and
        !isEmpty(record.DebitAccountNumber) and
        !isEmpty(record.Description)
    ),
    rejected: payload filter ((record) ->
        isEmpty(record.Amount) or
        isEmpty(record.CreditAccountNumber) or
        isEmpty(record.DebitAccountNumber) or
        isEmpty(record.Description)
    ) map ((record) ->
        record ++ {
            rejectionReason: "MISSING_MANDATORY_FIELD",
            missingFields: flatten([
                if (isEmpty(record.Amount)) "Amount" else null,
                if (isEmpty(record.CreditAccountNumber)) "CreditAccountNumber" else null,
                if (isEmpty(record.DebitAccountNumber)) "DebitAccountNumber" else null,
                if (isEmpty(record.Description)) "Description" else null
            ])
        }
    ),
    summary: {
        totalRecords: sizeOf(payload),
        validCount: sizeOf(payload filter ((record) ->
            !isEmpty(record.Amount) and
            !isEmpty(record.CreditAccountNumber) and
            !isEmpty(record.DebitAccountNumber) and
            !isEmpty(record.Description)
        )),
        rejectedCount: sizeOf(payload filter ((record) ->
            isEmpty(record.Amount) or
            isEmpty(record.CreditAccountNumber) or
            isEmpty(record.DebitAccountNumber) or
            isEmpty(record.Description)
        ))
    }
}

%dw 2.0
output application/json
---
{
    status: "COMPLETED",
    transactionId: vars.transactionId,
    summary: {
        totalRecords: sizeOf(vars.validRecords) + sizeOf(vars.rejectedRecords default []),
        processed: sizeOf(vars.validRecords),
        rejected: sizeOf(vars.rejectedRecords default []),
        successful: if (payload.status == "SUCCESS") sizeOf(vars.validRecords) else 0,
        failed: if (payload.status == "FAILED") sizeOf(vars.validRecords) else 0
    },
    batchResult: payload,
    timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ssZ"}
}
